    function fallback(){var field=document.createElement('textarea');field.value=link;field.style.cssText='position:fixed;left:-9999px';document.body.appendChild(field);field.select();try{if(document.execCommand('copy'))copied();else throw Error('copy failed');}catch(err){button.insertAdjacentHTML('afterend','<input class="job-link-fallback" readonly aria-label="Copie o link da vaga" value="'+esc(link)+'">');}field.remove();}
