  function overview(e,vs,cs) {var name=e.nome_fantasia||e.nomeFantasia||e.nome||sessionStorage.getItem('empresaNome')||'Sua empresa';var active=vs.filter(function(v){return jobStatus(v)==='active';}).length,pending=vs.filter(function(v){return jobStatus(v)==='pending';}).length,interviews=cs.filter(function(c){return norm(c.status).indexOf('entrevista')>=0;}).length;var metrics=[['Vagas ativas',active,'briefcase','','Vagas publicadas','jobs','active'],['Em análise',pending,'clock','orange','Aguardando aprovação','jobs','pending'],['Candidaturas',cs.length,'users','','Candidaturas recebidas','candidates','all'],['Entrevistas',interviews,'calendar','purple','Entrevistas agendadas','interviews','all']];return companyHero(e)+premiumRecruiterBanner(e)+'<div class="kpis kpis-premium-discreet">'+metrics.map(function(m){return '<button class="card kpi" data-action="nav" data-view="'+m[5]+'" data-filter="'+m[6]+'"><span class="icon '+m[3]+'">'+icon(m[2])+'</span><div><h2>'+m[0]+'</h2><strong>'+m[1]+'</strong><small>'+m[4]+'</small></div></button>';}).join('')+'</div>'+planStrip(e,vs)+'<div class="columns"><section class="card section"><div class="heading"><h2>Minhas vagas</h2><button class="link" data-action="nav" data-view="jobs">Ver todas '+icon('arrow')+'</button></div>'+table(vs.slice(0,3),cs,false)+'</section><section class="card section"><div class="heading"><h2>Novas candidaturas</h2><button class="link" data-action="nav" data-view="candidates">Ver todas '+icon('arrow')+'</button></div>'+candidateList(cs,vs)+'</section></div>'+performance(vs,cs);}
